import { useCallback, useEffect, useState } from 'react';
import { createProject, getProjects, getTasks } from './api';
import Task from './task';
import './dashboard.css';

function Dashboard({ user, userName, userRole, activePage: routedPage = 'Dashboard', onNavigate, onLogout }) {
  const [activePage, setActivePage] = useState(routedPage);
  const [search, setSearch] = useState('');
  const [taskStats, setTaskStats] = useState({ total: 0, completed: 0, remaining: 0 });
  const [workspaceTasks, setWorkspaceTasks] = useState([]);
  const [projects, setProjects] = useState([]);
  const [projectForm, setProjectForm] = useState({ name: '', description: '' });
  const [pageError, setPageError] = useState('');

  const updateTaskStats = useCallback((stats) => setTaskStats(stats), []);
  const progress = taskStats.total ? Math.round((taskStats.completed / taskStats.total) * 100) : 0;
  const pages = [
    ['Dashboard', '▥'], ['My Work', '▣'], ['My Tasks', '✓'], ['My Files', '▤'],
    ['My Calendar', '▦'], ['My Leads', '♧'], ['Projects', '⌘'], ['Admin', '♙'],
  ];

  useEffect(() => {
    setActivePage(routedPage);
  }, [routedPage]);
  const firstName = userName.trim().split(' ')[0];
  const roleMessage = userRole === 'Admin'
    ? 'You have a clear view of the whole workspace today.'
    : userRole === 'Manager'
      ? 'Keep your team aligned and moving forward today.'
      : 'A focused space for the work that matters today.';
  const summaryCards = (
    <section className="metric-grid" aria-label="Task summary">
      <article className="metric-card blue"><span>Total tasks</span><strong>{taskStats.total}</strong><small>Across your workspace</small></article>
      <article className="metric-card green"><span>Completed</span><strong>{taskStats.completed}</strong><small>{progress}% of your workload</small></article>
      <article className="metric-card purple"><span>Remaining</span><strong>{taskStats.remaining}</strong><small>{taskStats.remaining ? 'Keep the momentum going' : 'You are all caught up'}</small></article>
      <article className="metric-card pink"><span>Completion rate</span><strong>{progress}%</strong><small>Today&apos;s progress</small></article>
    </section>
  );

  useEffect(() => {
    Promise.all([getTasks(), getProjects()])
      .then(([taskResponse, projectResponse]) => {
        setWorkspaceTasks(taskResponse.data || []);
        setProjects(projectResponse.data || []);
      })
      .catch((loadError) => setPageError(loadError.message));
  }, []);

  async function handleCreateProject(event) {
    event.preventDefault();
    if (!projectForm.name.trim()) return;
    try {
      const response = await createProject(projectForm);
      setProjects((currentProjects) => [response.data, ...currentProjects]);
      setProjectForm({ name: '', description: '' });
      setPageError('');
    } catch (createError) {
      setPageError(createError.message);
    }
  }

  function renderWorkspacePage() {
    if (activePage === 'Projects') {
      return <section className="panel workspace-panel"><div className="panel-heading"><div><p className="dashboard-label">Workspace</p><h2>Projects</h2><p>Organize tasks into shared workstreams.</p></div><span>{projects.length} total</span></div>{userRole !== 'User' && <form className="workspace-form" onSubmit={handleCreateProject}><input value={projectForm.name} onChange={(event) => setProjectForm({ ...projectForm, name: event.target.value })} placeholder="Project name" aria-label="Project name" required /><input value={projectForm.description} onChange={(event) => setProjectForm({ ...projectForm, description: event.target.value })} placeholder="Description" aria-label="Project description" /><button type="submit">Create project</button></form>}<div className="workspace-list">{projects.length ? projects.map((project) => <article className="workspace-row" key={project._id}><span className="workspace-icon">⌘</span><div><strong>{project.name}</strong><p>{project.description || 'No description yet.'}</p></div><small>{project.members?.length || 0} members</small></article>) : <p className="task-empty">No projects yet.</p>}</div></section>;
    }

    const pageCopy = {
      'My Files': ['Files', 'File storage is ready for your workspace documents.', 'No files have been uploaded yet.'],
      'My Leads': ['Leads', 'Keep prospective work visible alongside your tasks.', 'No leads have been added yet.'],
      Admin: ['Admin', 'Manage workspace access and activity.', userRole === 'Admin' ? 'Admin controls are available from the user management tools.' : 'Admin access is required to manage this workspace.'],
    }[activePage];
    if (pageCopy) return <section className="panel workspace-panel"><p className="dashboard-label">Workspace</p><h2>{pageCopy[0]}</h2><p>{pageCopy[1]}</p><div className="empty-workspace"><span aria-hidden="true">{activePage === 'My Files' ? '▤' : activePage === 'My Leads' ? '♧' : '♙'}</span><strong>{pageCopy[2]}</strong></div></section>;

    if (activePage === 'My Calendar') {
      const datedTasks = workspaceTasks.filter((task) => task.dueDate).sort((a, b) => new Date(a.dueDate) - new Date(b.dueDate));
      return <section className="panel workspace-panel"><p className="dashboard-label">Workspace</p><h2>My Calendar</h2><p>Upcoming task deadlines from your workspace.</p><div className="workspace-list">{datedTasks.length ? datedTasks.map((task) => <article className="workspace-row" key={task._id}><span className="calendar-date">{new Date(task.dueDate).getDate()}</span><div><strong>{task.title}</strong><p>{new Date(task.dueDate).toLocaleDateString()}</p></div><small>{task.status}</small></article>) : <p className="task-empty">No dated tasks yet.</p>}</div></section>;
    }

    return <section className="workspace-page">{summaryCards}<Task search={search} compact={activePage === 'My Work'} userRole={userRole} onStats={updateTaskStats} assignedBy={userName} assignedTo={userName} assignedUserId={user?.id} /></section>;
  }

  return (
    <main className="dashboard-page">
      <div className="dashboard-shell">
        <aside className="dashboard-sidebar">
          <div className="product-logo"><span className="logo-icon">✓</span><span>Task Manager<small>WORKSPACE</small></span></div>
          <p className="menu-label">Menu</p>
          <nav aria-label="Main navigation">
            {pages.map(([page, icon]) => (
              <button className={`nav-item ${activePage === page ? 'active' : ''}`} type="button" key={page} onClick={() => { setActivePage(page); onNavigate?.(page); }}><span aria-hidden="true">{icon}</span>{page}{['My Leads', 'Projects', 'Admin'].includes(page) && <b aria-hidden="true">›</b>}</button>
            ))}
          </nav>
          <p className="menu-label general-label">General</p>
          <button className={`nav-item ${activePage === 'Settings' ? 'active' : ''}`} type="button" onClick={() => { setActivePage('Settings'); onNavigate?.('Settings'); }}><span aria-hidden="true">⚙</span>Settings</button>
          <button className="nav-item" type="button" onClick={onLogout}><span aria-hidden="true">↪</span>Logout</button>
          <div className="upgrade-box"><span className="upgrade-mark">✦</span><strong>{userRole} workspace</strong><p>Plan, track, and finish meaningful work.</p></div>
        </aside>

        <section className="dashboard-main">
          <header className="dashboard-topbar">
            <div><p className="dashboard-label">{activePage} / Overview</p><h1>Good morning, {firstName} <span aria-hidden="true">✦</span></h1><p>{roleMessage}</p></div>
            <div className="topbar-actions"><label className="search-box"><span>⌕</span><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search tasks..." aria-label="Search tasks" /></label><div className="account-box"><span className="user-avatar">{userName.charAt(0).toUpperCase()}</span><span><strong>{userName}</strong><small>{userRole} account</small></span></div></div>
          </header>

          {activePage === 'Dashboard' && (
            <>
              {summaryCards}
              <div className="dashboard-grid"><Task search={search} compact userRole={userRole} onStats={updateTaskStats} assignedBy={userName} assignedTo={userName} assignedUserId={user?.id} /><article className="panel progress-panel"><div className="panel-heading"><div><p className="dashboard-label">Your rhythm</p><h2>Today&apos;s progress</h2><p>{progress === 100 ? 'Everything is complete.' : 'Small steps add up.'}</p></div></div><div className="progress-circle" style={{ '--progress': `${progress}%` }}><strong>{progress}%</strong></div><p>{progress === 100 ? 'All tasks completed!' : `${taskStats.remaining} tasks left to finish.`}</p></article></div>
            </>
          )}

          {['My Work', 'My Tasks', 'My Files', 'My Calendar', 'My Leads', 'Projects', 'Admin'].includes(activePage) && renderWorkspacePage()}
          {pageError && <p className="task-error" role="alert">{pageError}</p>}
        </section>
      </div>
    </main>
  );
}

export default Dashboard;
